search_inference_docs.raw_response:
[
  {
    "criterion_id": "find_docs_succeeded",
    "kind": "tool_call_succeeded",
    "required": true,
    "tool_name": "find_docs"
  },
  {
    "criterion_id": "inference_endpoint_documentation_found",
    "kind": "predicate",
    "required": true,
    "expression": "any('inference' in str(r).lower() for r in obs['tool_results'])"
  },
  {
    "criterion_id": "no_errors",
    "kind": "predicate",
    "required": true,
    "expression": "len(obs.get('errors', [])) == 0"
  },
  {
    "criterion_id": "tool_results_not_empty",
    "kind": "predicate",
    "required": true,
    "expression": "len(obs['tool_results']) > 0"
  },
  {
    "criterion_id": "all_tools_succeeded",
    "kind": "predicate",
    "required": true,
    "expression": "all(r.get('_status') == 'ok' for r in obs['tool_results'])"
  }
]

